import '@emotion/react';

declare module '@emotion/react' {
  export interface Theme {
    colors: {
      background: string;
      text: string;
      primary: string;
    }
  }
}

export const theme = {
  light: {
    colors: {
      background: '#ffffff',
      text: '#333333',
      primary: '#4a90e2',
    }
  },
  dark: {
    colors: {
      background: '#1a1a1a',
      text: '#ffffff',
      primary: '#2c3e50',
    }
  }
};
